/usr/bin/bash -lc "python - <<'PY'
from lumen.models import Task
from lumen.client import LumenClient
import httpx

# Check Task constructor field order usability and serialization.
try:
    t = Task(id='t1', external_id='e1', payload={'x': 1})
    print('Task keyword ok', t, t.to_dict())
except Exception as exc:
    print('Task keyword error', type(exc).__name__, exc)

try:
    t = Task('t1', 'e1', {'x': 1})
    print('Task positional', t, t.to_dict())
except Exception as exc:
    print('Task positional error', type(exc).__name__, exc)

# Check raw path generation for unsafe ids.
def handler(request):
    print(request.method, request.url.path)
    return httpx.Response(200, json={'id':'p','name':'n','created_at':'now','status':'active','label_schema':{}})

with LumenClient('k', transport=httpx.MockTransport(handler), sleeper=lambda d: None) as c:
    try:
        c.projects.get('../x')
    except Exception as exc:
        print('path check error', type(exc).__name__, exc)
PY"

